"""HTML fragments that show a mark in context. Neighbours are generated by the kit; never third-party logos."""
from __future__ import annotations

from jinja2 import Environment

from .kit import circle, rect_centered, regular_polygon, ring, rrect_centered
from .kit.mark import Composite, Mark
from .render import with_size

MOCKUPS = ("phone-home", "browser-tab", "site-header-light", "site-header-dark", "avatar", "card", "sign-one-colour")
NEIGHBOUR_COLOURS = ["#3a7bd5", "#e94e77", "#2ecc71", "#f5a623", "#8e44ad", "#1abc9c", "#e74c3c", "#34495e", "#f1c40f", "#16a085",
                     "#d35400"]


def neighbour_icons(size: int = 60) -> list[str]:
    """Eleven generic app icons (coloured tiles with simple glyphs) for the shelf test."""
    icons = []
    for i, colour in enumerate(NEIGHBOUR_COLOURS):
        tile = rrect_centered(0, 0, 100, 100, 22)
        glyph = [circle(0, 0, 26), regular_polygon(0, 0, 30, 3, rotation=90), rect_centered(0, 0, 44, 14), ring(0, 0, 28, 10)][i % 4]
        # The glyph is an ink part drawn white: paper is the background, never a part's role.
        mark = Mark(symbol=Composite([(tile, "primary"), (glyph, "ink")]))
        svg = mark.to_svg("color", palette={"primary": colour, "ink": "#ffffff"})
        icons.append(with_size(svg, size, size))
    return icons


def render_mockup(env: Environment, kind: str, ctx: dict) -> str:
    if kind not in MOCKUPS:
        raise ValueError(f"unknown mockup {kind!r}")
    return env.get_template(f"mockups/{kind}.html").render(kind=kind, **ctx)
